/**
 * AtlasProp is one thing standing on the map — a pillar, a coffin, a pile of
 * bones — each naming WHAT it is and answering both blocking questions for
 * itself. Mirrors session.AtlasProp. Dungeon-absolute.
 *
 * THIS REPLACED `repeated Position occluders` on GetAtlasResponse in
 * session/v0.18.0 (rpg-toolkit#1130). That field was the subset of cells that
 * blocked sight, as bare coordinates, and it was wrong in two directions at
 * once. It could not say a pillar from a statue — rpg-project#227 recorded the
 * complaint as "a pillar and a statue are the same cell" — and it hardcoded ONE
 * answer to TWO independent questions: a coffin is walked around but seen over,
 * and a pile of bones is neither. A host that wants the old list back filters
 * this one on blocks_line_of_sight.
 *
 * @generated from message dnd5e.api.session.v1alpha1.AtlasProp
 */
export type AtlasProp = Message<"dnd5e.api.session.v1alpha1.AtlasProp"> & {
  /**
   * Ref names what this is, so a host can draw it.
   *
   * @generated from field: string ref = 1;
   */
  ref: string;

  /**
   * The cell it stands on, in dungeon-absolute space.
   *
   * @generated from field: dnd5e.api.session.v1alpha1.Position at = 2;
   */
  at?: Position | undefined;

  /**
   * Whether an entity may enter its cell.
   *
   * PLAIN bool, not `optional bool`, and the choice is deliberate on both of
   * these. The SDK had to strip `omitempty` from its four blocking flags
   * (rpg-toolkit#1136) because hand-rolled JSON carries no schema, so a false
   * vanished and a pile of bones — which blocks neither — serialised carrying no
   * blocking information at all, indistinguishable from a prop nobody declared
   * one for. Proto does not have that hole: false is the schema's default, and a
   * generated client materialises it whether or not the wire spends the bytes.
   *
   * `optional` would be worse than redundant here. It would invent a third
   * state, unspecified, that the producer cannot express: an atlas is the
   * projection of a RESOLVED world in which every prop already has both answers.
   * The `*bool` the composition spends one layer down (rpg-toolkit#1033) guards
   * a genuinely open question — was a capability SUPPLIED — and that question
   * has already been settled by the time anything reaches this seam.
   *
   * @generated from field: bool blocks_movement = 3;
   */
  blocksMovement: boolean;

  /**
   * Whether sight passes through its cell.
   *
   * @generated from field: bool blocks_line_of_sight = 4;
   */
  blocksLineOfSight: boolean;

  /**
   * The AUTHORED facing, verbatim from the dungeonspec `place[].facing` word
   * (rpg-project#261, vocabulary redefined by rpg-project#272). Empty means
   * not authored: render the asset's own default orientation, exactly
   * today's rendering.
   *
   * When present, it is one of the EIGHT true-compass names —
   * n|ne|e|se|s|sw|w|nw — and the SAME eight are valid under BOTH hex
   * orientations. Compass directions live in world space, so the vocabulary
   * does not depend on the atlas's hex orientation; walls have rendered
   * axis-true since rpg-toolkit#802, and a prop must be able to stand
   * squarely against a horizontal wall in a pointy-top dungeon whose hex
   * edges have no "n". This deliberately REDEFINES the four diagonal names
   * from #261's hex-edge semantics (pointy-top `ne` pointed at the 30° edge)
   * to true compass (`ne` is 45°) — rpg-project#272 records the ruling and
   * why no shipped content moves. The wire carries the WORD, never an angle:
   * the name-to-yaw map is ONE client-side calibrated table serving both
   * orientations, not something this transport derives or implies.
   *
   * GRID_KIND_SQUARE atlases carry no authored facings TODAY for a supply
   * reason, not a vocabulary one: the single producer of this field — the
   * dungeonspec dialect — authors hex dungeons only. The compass names are
   * grid-independent by construction, so a square authoring path, when one
   * exists, uses these same eight words; nothing here reserves a different
   * set for it.
   *
   * This is deliberately a different shape from `Placement.facing` (dnd5e/
   * api/v1alpha2/encounter/types.proto) — that field is a fixed hex-direction
   * INDEX for a runtime observation's turn-driven orientation; this one is a
   * world-space compass NAME authored in the dungeon builder, and the two
   * vocabularies do not interconvert.
   *
   * @generated from field: string facing = 5;
   */
  facing: string;

  /**
   * offset_x and offset_y are an authored within-cell visual nudge, each a
   * fraction of the cell size and each MUST be in [-0.5, 0.5]. Zero (the
   * default for both) means centered — indistinguishable on the wire from
   * "not authored," which is fine: both render identically, at cell center.
   *
   * VISUAL ONLY. The prop still occupies its whole cell for movement and
   * line of sight; nothing that computes rules may read these fields.
   *
   * @generated from field: float offset_x = 6;
   */
  offsetX: number;

  /**
   * @generated from field: float offset_y = 7;
   */
  offsetY: number;

  /**
   * offset_z is the authored height of the prop above the floor, as a
   * fraction of cell size, in [0, 3] (rpg-project#272). Zero (the default)
   * means on the floor — indistinguishable on the wire from "not authored,"
   * which is fine: both render identically, on the floor.
   *
   * Deliberately NOT bound to its siblings' within-cell ±0.5 clamp: raising
   * a prop well past one cell-height is the point (a skull onto an altar, a
   * torch onto a sconce line). VISUAL ONLY, like its two siblings.
   *
   * @generated from field: float offset_z = 8;
   */
  offsetZ: number;
};

